    {
        int taps = clamp(soft_shadow_taps, 1, SOFT_SHADOW_VOGEL_MAX);
        float inv_n = 1.0 / float(taps);
        float slot_phase = g_spot_slot * SOFT_NOISE_SLOT_PHASE;
        float phi = softShadowPhi(pr, slot_phase);
